#[path="../src/kernel.rs"] mod kernel;
use kernel::*;
fn init(n:usize)->Vec<f64>{(0..n).map(|i|0.45+0.12*(std::f64::consts::PI*(i as f64+0.5)/n as f64).cos()+0.03*(7.0*std::f64::consts::PI*(i as f64+0.5)/n as f64).cos()).collect()}
fn maxerr(a:&[f64],b:&[f64])->f64{a.iter().zip(b).map(|(x,y)|(x-y).abs()).fold(0.0,f64::max)}
#[test]fn ad_matches_independent_polynomial_direction(){for n in [2,7,16,64]{for eps in [0.0,1.0]{let m=Model::new(n,0.01*(n*n)as f64,2.0,0.4,eps).unwrap();let y=init(n);let v:Vec<_>=(0..n).map(|i|((i*7)as f64).sin()).collect();let mut values=Vec::new();for mode in [DerivativeMode::LocalAd,DerivativeMode::FullAd,DerivativeMode::Algebraic]{let mut z=vec![0.0;n];m.jvp_into(&y,&v,&mut z,mode,&mut Work::default()).unwrap();values.push(z);}assert!(maxerr(&values[0],&values[1])<1e-10);assert!(maxerr(&values[0],&values[2])<1e-10);}}}
#[test]fn exact_packet_refuses_broken_closure(){assert!(Model::new(16,2.0,2.0,0.4,1e-16).unwrap().packet(&[0.5;16],0.1).is_err());assert!(Model::new(7,2.0,2.0,0.4,0.0).unwrap().packet(&[0.5;7],0.1).is_err());}
#[test]fn packet_preserves_arbitrary_initial_modes_and_semigroup(){let n=64;let m=Model::new(n,40.96,2.0,0.4,0.0).unwrap();let y:Vec<_>=(0..n).map(|i|0.3+0.2*((i*i+17)as f64).sin()).collect();let a=m.packet(&y,0.1).unwrap();let b=m.packet(&m.packet(&y,0.03).unwrap(),0.07).unwrap();assert!(maxerr(&a,&b)<1e-13);let eps=1e-7;let tiny=m.packet(&y,eps).unwrap();let f=m.rhs(&y).unwrap();let e=tiny.iter().zip(&y).zip(&f).map(|((a,b),f)|((a-b)/eps-f).abs()).fold(0.0,f64::max);assert!(e<0.002,"derivative of physical flow {e}");}
#[test]fn constant_packet_agrees_with_riccati(){let m=Model::new(16,300.0,2.0,0.4,0.0).unwrap();let y=m.packet(&[0.5;16],0.2).unwrap();let b:f64=-1.6;let den=1.0+0.4*0.5*(b*0.2).exp_m1()/b;let exact=0.5*(b*0.2).exp()/den;assert!(y.iter().all(|x|(x-exact).abs()<2e-15));}
#[test]fn certificate_detects_hidden_interior_defect(){let m=Model::new(2,0.0,0.0,0.0,0.0).unwrap();let curve=Curve::from_controls(&m,0.0,0.1,vec![vec![0.5,0.8,0.5];2]).unwrap();let s=Segment::verify(&m,curve,0.0,&mut Work::default()).unwrap();assert!(s.defect()>5.9);assert!(s.endpoint_radius()>0.59);assert_eq!(s.curve().initial(),s.curve().endpoint());}
#[test]fn certificate_binds_model_and_domain(){let a=Model::new(2,1.0,2.0,0.4,1.0).unwrap();let b=Model::new(2,1.01,2.0,0.4,1.0).unwrap();let curve=Curve::from_controls(&a,0.0,0.1,vec![vec![0.5,0.4];2]).unwrap();assert!(Segment::verify(&b,curve,0.0,&mut Work::default()).is_err());let bad=Curve::from_controls(&a,0.0,0.1,vec![vec![0.5,1.1,0.4];2]).unwrap();assert!(Segment::verify(&a,bad,0.0,&mut Work::default()).is_err());}
#[test]fn interval_guards_and_cancellation(){assert!(Iv::new(2.0,1.0).is_err());assert!(Iv::point(f64::NAN).is_err());let x=Iv::point(0.3).unwrap();assert!(x.mul(x).unwrap().contains(0.09));assert!(x.div(Iv::new(-1.0,1.0).unwrap()).is_err());assert!(Iv::point(f64::MAX).unwrap().scale(2.0).is_err());let sub=Iv::point(f64::from_bits(1)).unwrap().scale(0.5).unwrap();assert!(sub.lo<=0.0&&sub.hi>=f64::from_bits(1));assert!(Iv{lo:2.0,hi:1.0}.add(Iv::zero()).is_err());}
#[test]fn adaptive_packet_has_continuous_radius_and_true_rollback(){let n=16;let m=Model::new(n,2.56,2.0,0.4,0.0).unwrap();let y=init(n);let cfg=IntegrationConfig{initial_h:0.2,max_h:0.2,..IntegrationConfig::default()};let times:Vec<_>=(0..=20).map(|i|0.2*i as f64/20.0).collect();let r=integrate(&m,&y,&times,&cfg,|_,y,h,w|Ok(Endpoint{state:m.packet_counted(y,h,w)?,method:"packet".into()})).unwrap();assert!(r.success,"{:?}",r.failure);assert!(r.rejected>0);assert_eq!(r.states.len(),21);let mut last=None;for t in &r.trials{if !t.accepted{assert_eq!(t.radius_before.to_bits(),t.radius_after.to_bits());if let Some(hash)=last{assert_eq!(hash,t.accepted_state_fingerprint);}}else{last=Some(t.accepted_state_fingerprint);}}for i in 0..=100{let t=0.2*i as f64/100.0;let(v,bound)=r.evaluate(t).unwrap();let actual=m.packet(&y,t).unwrap();assert!(maxerr(&v,&actual)<=bound);assert!(bound<=cfg.abs_tolerance);}println!("packet windows={}, reject={},radius={}",r.accepted,r.rejected,r.final_radius);}
#[test]fn quintic_reduces_certificate_window_work(){let m=Model::new(16,2.56,2.0,0.4,0.0).unwrap();let y=init(16);let ts=[0.0,0.2];let mut counts=Vec::new();for quintic in [false,true]{let cfg=IntegrationConfig{quintic,..IntegrationConfig::default()};let r=integrate(&m,&y,&ts,&cfg,|_,y,h,w|Ok(Endpoint{state:m.packet_counted(y,h,w)?,method:"packet".into()})).unwrap();assert!(r.success);counts.push(r.accepted);println!("quintic={quintic},windows={}",r.accepted);}assert!(counts[1]<counts[0]);}
#[test]fn failed_candidates_keep_partial_state_and_work(){let m=Model::new(2,1.0,2.0,0.4,0.0).unwrap();let y=[0.5;2];let cfg=IntegrationConfig{max_attempts:3,..IntegrationConfig::default()};let r=integrate(&m,&y,&[0.0,0.2],&cfg,|_,_,_,_|Err("forced failure".into())).unwrap();assert!(!r.success);assert_eq!(r.final_state,y);assert_eq!(r.final_t,0.0);assert_eq!(r.rejected,3);assert_eq!(r.work.candidate_failures,3);assert_eq!(r.states.len(),1);}
#[test]fn finite_shape_and_time_contracts_fail_closed(){let m=Model::new(2,1.0,2.0,0.4,0.0).unwrap();assert!(m.jvp(&[0.2,0.3],&[0.4]).is_err());assert!(m.rhs(&[0.2,f64::NAN]).is_err());assert!(Curve::from_controls(&m,0.1,0.1,vec![vec![0.2,0.3];2]).is_err());assert!(integrate(&m,&[0.5;2],&[0.0,0.0,0.2],&IntegrationConfig::default(),|_,_,_,_|panic!()).is_err());}
#[test]fn structured_shift_solve_matches_original_operator(){for n in [2,7,32]{let m=Model::new(n,0.01*(n*n)as f64,2.0,0.4,1.0).unwrap();let y=init(n);let rhs:Vec<_>=(0..n).map(|i|(i as f64+0.2).cos()).collect();for s in [1e-5,0.01,1.0,100.0]{let mut w=Work::default();let f=m.shift_factor(&y,s,&mut w).unwrap();let x=f.solve(&rhs,&mut w).unwrap();let j=m.jvp(&y,&x).unwrap();let residual=x.iter().zip(&j).zip(&rhs).map(|((x,j),b)|(x-s*j-b).abs()).fold(0.0,f64::max);assert!(residual<1e-10,"{n} {s} {residual}");}}}
